import{_ as o,a0 as p,w as h,s as r,ao as l,I as n,x as s,a1 as t,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"如何確定你的Linux發行版中有沒有某個軟件包 | LCTT x X-CMD","titleTemplate":false,"description":"如何確定你的Linux發行版中有沒有某個軟件包 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何確定你的Linux發行版中有沒有某個軟件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何確定你的Linux發行版中有沒有某個軟件包 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180607 Find If A Package Is Available For Your Linux Distribution","title":"如何確定你的Linux發行版中有沒有某個軟件包","tag":"201808","desc":""},"relativePath":"201808/20180607 Find If A Package Is Available For Your Linux Distribution.md","filePath":"[post].md"}'),d={name:"201808/20180607 Find If A Package Is Available For Your Linux Distribution.md"};function u(g,i,k,b,f,x){const a=p("Link");return h(),r("div",null,[i[33]||(i[33]=l('<h1 id="如何確定你的linux發行版中有沒有某個軟件包" tabindex="-1">如何確定你的Linux發行版中有沒有某個軟件包 <a class="header-anchor" href="#如何確定你的linux發行版中有沒有某個軟件包" aria-label="Permalink to “如何確定你的Linux發行版中有沒有某個軟件包”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/06/Whohas-720x340.png" alt=""></p><p>有時，你可能會想知道如何在你的 Linux 發行版上尋找一個特定的軟件包。或者，你僅僅只是想知道安裝在你的 Linux 上的軟件包有什麼版本。如果這就是你想知道的信息，你今天走運了。我正好知道一個小工具能幫你抓到上述信息，下面隆重推薦—— Whohas：這是一個命令列工具，它能一次查詢好幾個軟件包列表，以檢查的你軟件包是否存在。目前，whohas 支持 Arch、Debian、Fedora、Gentoo、Mandriva、openSUSE、Slackware、Source Mage、Ubuntu、FreeBSD、NetBSD、OpenBSD（LCTT 譯註：*BSD 不是 Linux）、Fink、MacPorts 和 Cygwin。使用這個小工具，軟件包的維護者能輕而易舉從別的 Linux 發行版裏找到 ebuilds、 pkgbuilds 等等類似的包定義文件。</p><p>Whohas 是用 Perl 語言開發的自由、開源的工具。</p><h3 id="在你的-linux-中尋找一個特定的包" tabindex="-1">在你的 Linux 中尋找一個特定的包 <a class="header-anchor" href="#在你的-linux-中尋找一個特定的包" aria-label="Permalink to “在你的 Linux 中尋找一個特定的包”">​</a></h3><h4 id="安裝-whohas" tabindex="-1">安裝 Whohas <a class="header-anchor" href="#安裝-whohas" aria-label="Permalink to “安裝 Whohas”">​</a></h4><p>Whohas 在 Debian、Ubuntu、Linux Mint 的默認軟件倉庫裏提供。如果你正在使用某種基於 DEB 的系統，你可以用如下命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install whohas</span></span></code></pre></div>',8)),n("p",null,[i[1]||(i[1]=s("對基於 Arch 的系統，",-1)),t(a,{href:"https://aur.archlinux.org/packages/whohas/"},{default:e(()=>[...i[0]||(i[0]=[s("AUR",-1)])]),_:1}),i[2]||(i[2]=s(" 裏就有提供 whohas。你能使用任何的 AUR 助手程序來安裝。",-1))]),n("p",null,[i[4]||(i[4]=s("使用 ",-1)),t(a,{href:"https://www.ostechnix.com/install-packer-arch-linux-2/"},{default:e(()=>[...i[3]||(i[3]=[s("Packer",-1)])]),_:1}),i[5]||(i[5]=s("：",-1))]),i[34]||(i[34]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ packer -S whohas</span></span></code></pre></div>',1)),n("p",null,[i[7]||(i[7]=s("或使用",-1)),t(a,{href:"https://www.ostechnix.com/trizen-lightweight-aur-package-manager-arch-based-systems/"},{default:e(()=>[...i[6]||(i[6]=[s("Trizen",-1)])]),_:1}),i[8]||(i[8]=s("：",-1))]),i[35]||(i[35]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ trizen -S whohas</span></span></code></pre></div>',1)),n("p",null,[i[10]||(i[10]=s("使用",-1)),t(a,{href:"https://www.ostechnix.com/yay-found-yet-another-reliable-aur-helper/"},{default:e(()=>[...i[9]||(i[9]=[s("Yay",-1)])]),_:1}),i[11]||(i[11]=s("：",-1))]),i[36]||(i[36]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yay -S whohas</span></span></code></pre></div>',1)),n("p",null,[i[13]||(i[13]=s("使用 ",-1)),t(a,{href:"https://www.ostechnix.com/install-yaourt-arch-linux/"},{default:e(()=>[...i[12]||(i[12]=[s("Yaourt",-1)])]),_:1}),i[14]||(i[14]=s("：",-1))]),i[37]||(i[37]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yaourt -S whohas</span></span></code></pre></div>',1)),n("p",null,[i[16]||(i[16]=s("在別的 Linux 發行版上，從",-1)),t(a,{href:"http://www.philippwesche.org/200811/whohas/intro.html"},{default:e(()=>[...i[15]||(i[15]=[s("這裏",-1)])]),_:1}),i[17]||(i[17]=s("下載源代碼並手工編譯安裝。",-1))]),i[38]||(i[38]=l(`<h4 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to “使用方法”">​</a></h4><p>Whohas 的主要目標是想讓你知道：</p><ul><li>哪個 Linux 發佈版提供了用户依賴的包。</li><li>對於各個 Linux 發行版，指定的軟件包是什麼版本，或者在這個 Linux 發行版的各個不同版本上，指定的軟件包是什麼版本。</li></ul><p>讓我們試試看上面的的功能，比如説，哪個 Linux 發行版裏有 vim 這個軟件？我們可以運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whohas vim</span></span></code></pre></div><p>這個命令將會顯示所有包含可安裝的 vim 的 Linux 發行版的信息，包括包的大小，倉庫地址和下載URL。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/06/whohas-1.png" alt=""></p><p>你甚至可以通過管道將輸出的結果按照發行版的字母排序，只需加入 <code>sort</code> 命令即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whohas vim | sort</span></span></code></pre></div><p>請注意上述命令將會顯示所有以 vim 開頭的軟件包，包括 vim-spell、vimcommander、vimpager 等等。你可以繼續使用 Linux 的 <code>grep</code> 命令在 “vim” 的前後加上空格來縮小你的搜索範圍，直到滿意為止。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whohas vim | sort | grep &quot; vim&quot;</span></span>
<span class="line"><span>$ whohas vim | sort | grep &quot;vim &quot;</span></span>
<span class="line"><span>$ whohas vim | sort | grep &quot; vim &quot;</span></span></code></pre></div><p>所有將空格放在包名字前面的搜索將會顯示以包名字結尾的包。所有將空格放在包名字後面的搜索將會顯示以包名字開頭的包。前後都有空格將會嚴格匹配。</p><p>又或者，你就使用 <code>--strict</code> 來嚴格限制結果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whohas --strict vim</span></span></code></pre></div><p>有時，你想知道一個包在不在一個特定的 Linux 發行版裏。例如，你想知道 vim 是否在 Arch Linux 裏，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whohas vim | grep &quot;^Arch&quot;</span></span></code></pre></div><p>（LCTT譯註：在結果裏搜索以 Arch 開頭的 Linux）</p><p>Linux 發行版的命名縮寫為：&#39;archlinux&#39;、&#39;cygwin&#39;、&#39;debian&#39;、&#39;fedora&#39;、 &#39;fink&#39;、&#39;freebsd&#39;、&#39;gentoo&#39;、&#39;mandriva&#39;、&#39;macports&#39;、&#39;netbsd&#39;、&#39;openbsd&#39;、&#39;opensuse&#39;、&#39;slackware&#39;、&#39;sourcemage&#39; 和 &#39;ubuntu&#39;。</p><p>你也可以用 <code>-d</code> 選項來得到同樣的結果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whohas -d archlinux vim</span></span></code></pre></div><p>這個命令將在僅僅 Arch Linux 發行版下搜索 vim 包。</p><p>如果要在多個 Linux 發行版下搜索，如 &#39;archlinux&#39;、&#39;ubuntu&#39;，請使用如下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whohas -d archlinux,ubuntu vim</span></span></code></pre></div><p>你甚至可以用 <code>whohas</code> 來查找哪個發行版有 whohas 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whohas whohas</span></span></code></pre></div><p>更詳細的信息，請參照手冊。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man whohas</span></span></code></pre></div><h4 id="最後的話" tabindex="-1">最後的話 <a class="header-anchor" href="#最後的話" aria-label="Permalink to “最後的話”">​</a></h4><p>當然，任何一個 Linux 發行版的包管理器都能輕鬆的在對應的軟件倉庫裏找到自己管理的包。不過，whohas 幫你整合並比較了在不同的 Linux 發行版下指定的軟件包信息，這樣你能輕易的跨平台之間進行比較。試一下 whohas，你一定不會失望的。</p><p>好了，今天就到這裏吧，希望前面講的對你有用，下次我還會帶來更多好東西！！</p><p>歐耶！</p><hr>`,32)),n("p",null,[i[19]||(i[19]=s("via: ",-1)),t(a,{href:"https://www.ostechnix.com/find-if-a-package-is-available-for-your-linux-distribution/"},{default:e(()=>[...i[18]||(i[18]=[s("https://www.ostechnix.com/find-if-a-package-is-available-for-your-linux-distribution/",-1)])]),_:1})]),n("p",null,[i[24]||(i[24]=s("作者：",-1)),t(a,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...i[20]||(i[20]=[s("SK",-1)])]),_:1}),i[25]||(i[25]=s(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...i[21]||(i[21]=[s("lujun9972",-1)])]),_:1}),i[26]||(i[26]=s(" 譯者：",-1)),t(a,{href:"https://github.com/davidchenliang"},{default:e(()=>[...i[22]||(i[22]=[s("DavidChenLiang",-1)])]),_:1}),i[27]||(i[27]=s(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:e(()=>[...i[23]||(i[23]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[30]||(i[30]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[28]||(i[28]=[s("LCTT",-1)])]),_:1}),i[31]||(i[31]=s(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...i[29]||(i[29]=[s("Linux中國",-1)])]),_:1}),i[32]||(i[32]=s(" 榮譽推出",-1))])])}const v=o(d,[["render",u]]);export{c as __pageData,v as default};
